#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyTypeClass {
    IntegerType,
    FloatingType,
    ComplexType,
    BooleanType,
    ScalarType,
    NumberType,
    InexactType,
    Int8Type,
    Int16Type,
    Int32Type,
    Int64Type,
    UInt8Type,
    UInt16Type,
    UInt32Type,
    UInt64Type,
    Float32Type,
    Float64Type,
    Complex64Type,
    Complex128Type,
    ObjectType,
}

pub fn issubclass_(arg1: NumpyTypeClass, arg2: NumpyTypeClass) -> bool {
    // Reflexivity
    if arg1 == arg2 {
        return true;
    }

    // Only the directly listed subclass relations (no transitive closure).
    match (arg1, arg2) {
        // Integer leaves
        (NumpyTypeClass::Int8Type,  NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::Int16Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::Int32Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::Int64Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::UInt8Type,  NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::UInt16Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::UInt32Type, NumpyTypeClass::IntegerType) => true,
        (NumpyTypeClass::UInt64Type, NumpyTypeClass::IntegerType) => true,

        // Floating-point leaves
        (NumpyTypeClass::Float32Type, NumpyTypeClass::FloatingType) => true,
        (NumpyTypeClass::Float64Type, NumpyTypeClass::FloatingType) => true,

        // Complex leaves
        (NumpyTypeClass::Complex64Type,  NumpyTypeClass::ComplexType) => true,
        (NumpyTypeClass::Complex128Type, NumpyTypeClass::ComplexType) => true,

        // Mid-level relations
        (NumpyTypeClass::IntegerType,  NumpyTypeClass::NumberType)  => true,
        (NumpyTypeClass::FloatingType, NumpyTypeClass::InexactType) => true,
        (NumpyTypeClass::FloatingType, NumpyTypeClass::NumberType)  => true,
        (NumpyTypeClass::ComplexType,  NumpyTypeClass::InexactType) => true,
        (NumpyTypeClass::ComplexType,  NumpyTypeClass::NumberType)  => true,

        // Top-level scalar relations
        (NumpyTypeClass::NumberType,   NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::BooleanType,  NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::IntegerType,  NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::FloatingType, NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::ComplexType,  NumpyTypeClass::ScalarType) => true,
        (NumpyTypeClass::InexactType,  NumpyTypeClass::ScalarType) => true,

        // Anything else is not a direct subclass
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_reflexive() {
        for &ty in &[
            NumpyTypeClass::IntegerType,
            NumpyTypeClass::Int32Type,
            NumpyTypeClass::Float64Type,
            NumpyTypeClass::ObjectType,
        ] {
            assert!(issubclass_(ty, ty));
        }
    }

    #[test]
    fn test_direct_relations() {
        assert!(issubclass_(NumpyTypeClass::Int32Type, NumpyTypeClass::IntegerType));
        assert!(issubclass_(NumpyTypeClass::Float32Type, NumpyTypeClass::FloatingType));
        assert!(issubclass_(NumpyTypeClass::Complex128Type, NumpyTypeClass::ComplexType));
        assert!(issubclass_(NumpyTypeClass::IntegerType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::FloatingType, NumpyTypeClass::InexactType));
        assert!(issubclass_(NumpyTypeClass::FloatingType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::ComplexType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::NumberType, NumpyTypeClass::ScalarType));
        assert!(issubclass_(NumpyTypeClass::BooleanType, NumpyTypeClass::ScalarType));
        assert!(issubclass_(NumpyTypeClass::InexactType, NumpyTypeClass::ScalarType));
    }

    #[test]
    fn test_non_transitive() {
        // Even though Int32Type -> IntegerType and IntegerType -> NumberType,
        // we do not consider Int32Type -> NumberType directly.
        assert!(!issubclass_(NumpyTypeClass::Int32Type, NumpyTypeClass::NumberType));
        // Likewise, Complex64Type is not directly a subclass of NumberType.
        assert!(!issubclass_(NumpyTypeClass::Complex64Type, NumpyTypeClass::NumberType));
        // ObjectType is only reflexively a subclass of itself.
        assert!(!issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::ScalarType));
    }
}